const data = $input.first().json;

const toolCall = data.body.message.toolCalls[0];

const args = toolCall.function["arguments"];

return [
  {
    json: {
      starttime: args.starttime,
      endtime: args.endtime,
      timeZone: "Asia/Manila",
      toolCallId: toolCall.id
    }
  }
];;

// Get the incoming webhook data
const input = $input.first().json;

// Safely retrieve a property by its key name
// This avoids direct access to restricted properties such as "arguments".
function getProperty(obj, key) {
  if (!obj || typeof obj !== 'object') {
    return undefined;
  }

  const actualKey = Object.keys(obj).find(k => k === key);

  return actualKey !== undefined ? obj[actualKey] : undefined;
}

// Get body
const body = getProperty(input, 'body');

// Get message
const message = getProperty(body, 'message');

// Get toolCalls
const toolCalls = getProperty(message, 'toolCalls');

if (!Array.isArray(toolCalls) || toolCalls.length === 0) {
  throw new Error('No toolCalls found in webhook data.');
}

// Get the first tool call
const toolCall = toolCalls[0];

// Get tool call ID
const toolCallID = getProperty(toolCall, 'id') || '';

// Get function
const func = getProperty(toolCall, 'function');

if (!func) {
  throw new Error('No function object found inside toolCall.');
}

// Get function name
const functionName = getProperty(func, 'name') || '';

// Get arguments safely WITHOUT using .arguments
let args = getProperty(func, 'arguments');

if (args === undefined || args === null) {
  throw new Error('No arguments found inside toolCall function.');
}

// If arguments is a JSON string, convert it to an object
if (typeof args === 'string') {
  try {
    args = JSON.parse(args);
  } catch (error) {
    throw new Error(
      'The tool arguments could not be parsed as JSON.\nReceived:\n' + args
    );
  }
}

// Extract all required fields
const title = getProperty(args, 'title') || '';
const name = getProperty(args, 'name') || '';
const email = getProperty(args, 'email') || '';
const notes = getProperty(args, 'notes') || '';

const starttime = getProperty(args, 'starttime') || '';
const endtime = getProperty(args, 'endtime') || '';

// Return clean data
return [
  {
    json: {
      toolCallID: toolCallID,
      functionName: functionName,

      title: title,
      name: name,
      email: email,
      notes: notes,

      starttime: starttime,
      endtime: endtime,

      timezone: 'Asia/Manila'
    }
  }
];

const escapeStringForJson = (str) => {
    return str
        .replace(/\\/g, '\\\\') // Escape backslashes
        .replace(/"/g, '\\"')    // Escape double quotes
        .replace(/\n/g, '\\n')   // Escape newlines
        .replace(/\r/g, '\\r')   // Escape carriage returns
        .replace(/\t/g, '\\t');  // Escape tabs
};

// Escape the notes field
$input.item.json.notes = escapeStringForJson($input.item.json.notes);

return $input.item;

// Get all input items
const items = $input.all();

// Loop through each item
for (const item of items) {
  // Get the values from the current item's JSON data
  const startTimeUTC = item.json.starttime;
  const endTimeUTC = item.json.endtime;
  const targetTimeZone = item.json.timeZone; // e.g., "America/Chicago"

  // Basic validation: ensure the necessary fields exist
  if (!startTimeUTC || !endTimeUTC || !targetTimeZone) {
    console.warn(`Skipping item due to missing time data or timezone. Item JSON: ${JSON.stringify(item.json)}`);
    item.json.conversionError = "Missing starttime, endtime, or timeZone";
    continue; // Move to the next item
  }

  try {
    // --- Start Time Conversion ---
    // Parse the original UTC ISO string using Luxon (NO $ prefix)
    const startDt = luxon.DateTime.fromISO(startTimeUTC, { zone: 'utc' });

    // Convert the DateTime object to the target timezone
    const startDtTargetZone = startDt.setZone(targetTimeZone);

    // Check if the conversion was valid
    if (!startDtTargetZone.isValid) {
      throw new Error(`Failed to convert start time. Reason: ${startDtTargetZone.invalidReason || 'Unknown'}`);
    }

    // Format the result back into an ISO string with the correct offset
    item.json.starttime = startDtTargetZone.toISO();

    // --- End Time Conversion ---
    // Parse the original UTC ISO string using Luxon (NO $ prefix)
    const endDt = luxon.DateTime.fromISO(endTimeUTC, { zone: 'utc' });

    // Convert the DateTime object to the target timezone
    const endDtTargetZone = endDt.setZone(targetTimeZone);

     // Check if the conversion was valid
    if (!endDtTargetZone.isValid) {
      throw new Error(`Failed to convert end time. Reason: ${endDtTargetZone.invalidReason || 'Unknown'}`);
    }

    // Format the result back into an ISO string with the correct offset
    item.json.endtime = endDtTargetZone.toISO();

    // Optionally remove the error flag if conversion was successful this time
    delete item.json.conversionError;

  } catch (error) {
    console.error(`Error converting time for item: ${JSON.stringify(item.json)}. Error: ${error.message}`);
    // Add/update the error flag to the item's JSON
    item.json.conversionError = error.message;
  }
}
// Return the modified array of items
return items;

function replaceValue(value) {
  if (error.message.include('no_available_users_found_error')) {
    return "This time slot is no longer available.";
  }
  return value;
}

$input.item.json.message = replaceValue($input.item.json.error.description);

return $input.item;

