// the restricted "arguments" property.
// ============================================================

const input = $input.first().json;


// ------------------------------------------------------------
// Safely get a property by its name
// ------------------------------------------------------------
function getProperty(object, propertyName) {
  if (!object || typeof object !== 'object') {
    return undefined;
  }

  const key = Object.keys(object).find(
    k => k === propertyName
  );

  return key !== undefined ? object[key] : undefined;
}


// ------------------------------------------------------------
// Find an object containing the tool-call arguments.
// This searches recursively instead of using:
//
// .function.arguments
// ------------------------------------------------------------
function findArgumentsObject(object) {
  if (!object || typeof object !== 'object') {
    return null;
  }

  // Check the current object
  const keys = Object.keys(object);

  const argumentKey = keys.find(
    key => key === 'arguments'
  );

  if (argumentKey !== undefined) {
    let value = object[argumentKey];

    // Arguments can sometimes arrive as a JSON string
    if (typeof value === 'string') {
      try {
        value = JSON.parse(value);
      } catch (error) {
        return null;
      }
    }

    if (value && typeof value === 'object') {
      return value;
    }
  }

  // Search child objects
  for (const key of keys) {
    const value = object[key];

    if (value && typeof value === 'object') {
      const result = findArgumentsObject(value);

      if (result) {
        return result;
      }
    }
  }

  return null;
}


// ------------------------------------------------------------
// Find the arguments object
// ------------------------------------------------------------
const args = findArgumentsObject(input);

if (!args) {
  throw new Error(
    'Could not find the tool-call arguments in the webhook data.'
  );
}


// ------------------------------------------------------------
// Helper for extracting fields
// Supports different capitalization/spelling.
// ------------------------------------------------------------
function getValue(object, possibleNames) {
  for (const name of possibleNames) {
    const value = getProperty(object, name);

    if (
      value !== undefined &&
      value !== null
    ) {
      return value;
    }
  }

  return '';
}


// ------------------------------------------------------------
// Extract tool arguments
// ------------------------------------------------------------

const name = getValue(args, [
  'name',
  'Name'
]);

const email = getValue(args, [
  'email',
  'Email'
]);

const starttime = getValue(args, [
  'starttime',
  'Starttime',
  'startTime',
  'StartTime'
]);

const endtime = getValue(args, [
  'endtime',
  'Endtime',
  'endTime',
  'EndTime'
]);

const title = getValue(args, [
  'title',
  'Title'
]);

const notes = getValue(args, [
  'notes',
  'Notes'
]);

const Cancelnotes = getValue(args, [
  'Cancelnotes',
  'cancelnotes',
  'CancelNotes',
  'cancelNotes'
]);

const Rescheduled_starttime = getValue(args, [
  'Rescheduled_starttime',
  'rescheduled_starttime',
  'RescheduledStarttime',
  'rescheduledStarttime'
]);

const Rescheduled_endtime = getValue(args, [
  'Rescheduled_endtime',
  'rescheduled_endtime',
  'RescheduledEndtime',
  'rescheduledEndtime'
]);


// ------------------------------------------------------------
// Get tool call ID
// ------------------------------------------------------------

let toolCallID = '';

function findToolCallID(object) {
  if (!object || typeof object !== 'object') {
    return '';
  }

  if (Object.prototype.hasOwnProperty.call(object, 'id')) {
    const value = object.id;

    if (
      typeof value === 'string' &&
      value.startsWith('call_')
    ) {
      return value;
    }
  }

  for (const key of Object.keys(object)) {
    const value = object[key];

    if (value && typeof value === 'object') {
      const result = findToolCallID(value);

      if (result) {
        return result;
      }
    }
  }

  return '';
}

toolCallID = findToolCallID(input);


// ------------------------------------------------------------
// Get customer number if available
// ------------------------------------------------------------

let customerNumber = '';

const body = getProperty(input, 'body');
const message = getProperty(body, 'message');
const call = getProperty(message, 'call');
const customer = getProperty(call, 'customer');

if (customer) {
  customerNumber =
    getProperty(customer, 'number') || '';
}


// ------------------------------------------------------------
// Return CLEAN data
// ------------------------------------------------------------

return [
  {
    json: {
      toolCallID,

      name,
      email,

      title,
      notes,
      Cancelnotes,

      starttime,
      endtime,

      Rescheduled_starttime,
      Rescheduled_endtime,

      customerNumber,

      timezone: 'Asia/Manila'
    }
  }
