// Helper: safely find a property without directly referencing
// restricted properties such as "arguments"
// ------------------------------------------------------------
function getProperty(obj, propertyName) {
  if (!obj || typeof obj !== 'object') {
    return undefined;
  }

  const key = Object.keys(obj).find(
    key => key === propertyName
  );

  return key !== undefined ? obj[key] : undefined;
}


// ------------------------------------------------------------
// 1. Get body
// ------------------------------------------------------------
const body = getProperty(input, 'body');

if (!body) {
  throw new Error('Webhook body was not found.');
}


// ------------------------------------------------------------
// 2. Get message
// ------------------------------------------------------------
const message = getProperty(body, 'message');

if (!message) {
  throw new Error('Message object was not found.');
}


// ------------------------------------------------------------
// 3. Find the tool call list
//
// Your screenshot shows "toolCallList", but some n8n/AI
// payloads may use "toolCalls", so we support both.
// ------------------------------------------------------------
let toolCalls = getProperty(message, 'toolCallList');

if (!Array.isArray(toolCalls)) {
  toolCalls = getProperty(message, 'toolCalls');
}

if (!Array.isArray(toolCalls) || toolCalls.length === 0) {
  throw new Error(
    'No tool call list was found. Expected toolCallList or toolCalls.'
  );
}


// ------------------------------------------------------------
// 4. Get the first tool call
// ------------------------------------------------------------
const toolCall = toolCalls[0];


// ------------------------------------------------------------
// 5. Get tool call ID
// ------------------------------------------------------------
const toolCallID = getProperty(toolCall, 'id') || '';


// ------------------------------------------------------------
// 6. Get function object
// ------------------------------------------------------------
const func = getProperty(toolCall, 'function');


// Some payload structures may put the function name/arguments
// directly in the tool call. Support both structures.
const functionObject = func || toolCall;


// ------------------------------------------------------------
// 7. Find "arguments" dynamically
//
// IMPORTANT:
// We DO NOT use:
//     functionObject.arguments
//
// Instead we locate the key dynamically.
// ------------------------------------------------------------
const argumentKey = Object.keys(functionObject).find(
  key => key === 'arguments'
);

if (argumentKey === undefined) {
  throw new Error(
    'The tool call does not contain an arguments object.'
  );
}


// Get arguments using the dynamically discovered key
let args = functionObject[argumentKey];


// ------------------------------------------------------------
// 8. If arguments are returned as a JSON string, parse them
// ------------------------------------------------------------
if (typeof args === 'string') {
  try {
    args = JSON.parse(args);
  } catch (error) {
    throw new Error(
      'Unable to parse tool arguments as JSON.\n\n' +
      args
    );
  }
}

if (!args || typeof args !== 'object') {
  throw new Error(
    'Tool arguments are not a valid object.'
  );
}


// ------------------------------------------------------------
// 9. Get function name
// ------------------------------------------------------------
const functionName =
  getProperty(functionObject, 'name') ||
  getProperty(toolCall, 'name') ||
  '';


// ------------------------------------------------------------
// 10. Extract argument fields
// ------------------------------------------------------------
const name =
  getProperty(args, 'name') || '';

const email =
  getProperty(args, 'email') || '';

const starttime =
  getProperty(args, 'starttime') || '';

const endtime =
  getProperty(args, 'endtime') || '';

const Rescheduled_starttime =
  getProperty(args, 'Rescheduled_starttime') || '';

const Rescheduled_endtime =
  getProperty(args, 'Rescheduled_endtime') || '';


// ------------------------------------------------------------
// 11. Get customer number
//
// Based on your screenshot:
// body → message → call → customer → number
// ------------------------------------------------------------
const call = getProperty(message, 'call');

const customer =
  getProperty(call, 'customer');

const customerNumber =
  getProperty(customer, 'number') || '';


// ------------------------------------------------------------
// 12. Return clean data
// ------------------------------------------------------------
return [
  {
    json: {
      toolCallID: toolCallID,

      functionName: functionName,

      name: name,
      email: email,

      starttime: starttime,
      endtime: endtime,

      Rescheduled_starttime: Rescheduled_starttime,
      Rescheduled_endtime: Rescheduled_endtime,

      customerNumber: customerNumber,

      timezone: 'Asia/Manila'
    }
  }
];

